import{_ as r,a0 as t,w as o,s as d,ao as l,I as n,x as s,a1 as p,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"在 Linux 上用 zram 替代传统交换空间 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上用 zram 替代传统交换空间 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上用 zram 替代传统交换空间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上用 zram 替代传统交换空间 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221111.4 ⭐️⭐️ Drop swap for zram on Linux","title":"在 Linux 上用 zram 替代传统交换空间","tag":"202301","desc":""},"relativePath":"202301/20221111.4 ⭐️⭐️ Drop swap for zram on Linux.md","filePath":"[post].md"}'),m={name:"202301/20221111.4 ⭐️⭐️ Drop swap for zram on Linux.md"};function c(h,a,g,z,u,k){const e=t("Link");return o(),d("div",null,[a[22]||(a[22]=l(`<h1 id="在-linux-上用-zram-替代传统交换空间" tabindex="-1">在 Linux 上用 zram 替代传统交换空间 <a class="header-anchor" href="#在-linux-上用-zram-替代传统交换空间" aria-label="Permalink to “在 Linux 上用 zram 替代传统交换空间”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202301/28/113826twvkkbrso9ws2kss.jpg" alt=""></p><blockquote><p>zram 是一个用于创建内存压缩缓存的工具，特别是可以用作交换空间。</p></blockquote><p>我在我的电脑上花了很多时间（我是说工作），我发现了很多有趣的东西。其中最近引起我注意的是 <code>zram0</code> 设备。我是在几个月前写一篇文章时第一次注意到它，它显示在 <code>lsblk</code> 命令的输出中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lsblk</span></span>
<span class="line"><span>NAME          MAJ:MIN RM   SIZE RO TYPE MOUNTPOINTS</span></span>
<span class="line"><span>sda             8:0    0 931.5G  0 disk</span></span>
<span class="line"><span>├─sda1          8:1    0   600M  0 part</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>zram0         252:0    0     8G  0 disk [SWAP]</span></span></code></pre></div><p>它被识别为交换空间，这就是首先引起我的好奇心的原因，所以我做了一些研究。zram 最初被称为 “<ruby>压缩缓存<rt>compcache</rt></ruby>”，即 “压缩的高速缓存”。事实证明，zram 是一个用于创建内存内压缩缓存的工具，特别是作为交换空间使用。</p><p>但为什么呢？</p><p>当我开始研究 zram 时，我只发现了几篇关于将 zram 用于交换空间的基础文章。起初，这对我来说似乎有点违反直觉。毕竟，如果你的内存快用完了，你把页面交换到内存中的虚拟驱动器中，有什么好处呢？</p>`,8)),n("p",null,[a[2]||(a[2]=s("然后我找到了 Fedora 项目的维基页面，它提议使用 ",-1)),n("ruby",null,[p(e,{href:"https://fedoraproject.org/wiki/Changes/SwapOnZRAM"},{default:i(()=>[...a[0]||(a[0]=[s("zram 交换空间",-1)])]),_:1}),a[1]||(a[1]=n("rt",null,"swap-on-zram",-1))]),a[3]||(a[3]=s("。该建议说：“交换是有用的，除了它的速度很慢。zram 是一个使用了压缩的内存驱动器。在启动时创建一个 zram 交换空间，并且不再使用默认的交换分区。”",-1))]),a[23]||(a[23]=n("p",null,"该页面的其余部分是关于它的细节、好处、副作用和反馈。",-1)),a[24]||(a[24]=n("h3",{id:"linux-上用于交换空间的-zram",tabindex:"-1"},[s("Linux 上用于交换空间的 zram "),n("a",{class:"header-anchor",href:"#linux-上用于交换空间的-zram","aria-label":"Permalink to “Linux 上用于交换空间的 zram”"},"​")],-1)),a[25]||(a[25]=n("p",null,"使用 zram 作为交换空间，与常规的基于分区或基于文件的交换空间做的事情相同。当内存压力过大时，一些最近使用最少的数据会被移到交换空间。平均来说，它会被压缩到其原始大小的 50% 左右，并被放置在内存的 zram 空间中。这比将这些内存页存储在硬盘上要快得多，并可以释放出它所使用的内存用于其他用途。",-1)),a[26]||(a[26]=n("h3",{id:"节省交换空间",tabindex:"-1"},[s("节省交换空间 "),n("a",{class:"header-anchor",href:"#节省交换空间","aria-label":"Permalink to “节省交换空间”"},"​")],-1)),n("p",null,[a[5]||(a[5]=s("我试图找到关于配置多少交换空间或 zram 交换空间的总结建议。这使我重新回顾了交换空间的设置，以及我之前的文章《",-1)),p(e,{href:"https://opensource.com/article/19/2/swap-space-poll"},{default:i(()=>[...a[4]||(a[4]=[s("现代 Linux 系统的正确交换空间是多少？",-1)])]),_:1}),a[6]||(a[6]=s("》。就我所知，从 RHEL 和 Fedora 的最新文档来看，推荐的交换空间数量并没有改变。不过，该文档忽略了 zram 的使用。",-1))]),a[27]||(a[27]=l(`<p>然而，在不使用 zram 的旧版 Linux 或 zram 被禁用的情况下，之前文章中的表格仍然为交换空间的分配提供了一个好的起点。</p><p>我找到的关于 zram 功能的文档在 zram 如何根据内存大小分配空间，以及分配给 zram 交换空间的数量方面是不一致的。</p><p>由于缺乏权威性的文档，我进行了一些实验来凭经验确定用于分配 zram 交换空间的算法。我为此使用了我自己的物理和虚拟系统。结果很有趣，与我迄今为止发现的任何文档都不一致。</p><p>在所有足够大的系统上，zram 的默认大小是 8GB，但在内存较小的主机上通常会大大减少。在我用于测试的一台虚拟机（VM）上，可以访问 4GB 的内存，zram 的虚拟交换空间被分配为 3.8GB。我的一台旧戴尔电脑拥有 8GB 的内存，zram 被设置为 7.6GB。当内存减少到 2GB 时，zram 就减少到 1.9GB。</p><p>我拥有的所有内存超过 8GB 的物理和虚拟主机都显示正好是 8GB 的 zram。这包括我拥有 64GB 内存的主工作站和其他拥有 16GB 或 32GB 内存的主机。</p><p>基于这几个数据点，我可以得出这样的结论：目前的默认设置是最多 8GB 的 zram，而在 8GB 或以下的主机上，zram 占内存的 95%。</p><p>我读过一些文章，其中提到了 zram 交换空间的其他大小，甚至高达 100% 的内存，但这些似乎都是理论上的，而不是现实。</p><p>你的发行版可能不同，但这里是 Fedora 和类似发行版的实际 zram 交换空间的分配情况：</p><ul><li>内存 ⇐ 8 GB：0.95 × 内存</li><li>内存 &gt; 8 GB:8 GB</li></ul><p>请注意，zram 交换空间大小的算法并没有基于对任何给定的现实世界的系统或应用程序的 “最佳” 交换大小的建议。这种 zram 交换空间的分配是一种相当概率性的方法，它应该在广泛的 Linux 主机上运行良好。然而，最大的 zram 交换空间大小被配置为 8GB，而且我一直推荐 8GB 作为传统交换空间的最大容量，我想我可以说它反映了 zram 交换空间的最佳大小。</p><h3 id="管理-zram-交换空间" tabindex="-1">管理 zram 交换空间 <a class="header-anchor" href="#管理-zram-交换空间" aria-label="Permalink to “管理 zram 交换空间”">​</a></h3><p>zram 的默认值保存在 <code>/usr/lib/systemd/zram-generator.conf</code> 配置文件中。以下是我的一个测试虚拟机，分配了 5097GB 的内存。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /usr/lib/systemd/zram-generator.conf</span></span>
<span class="line"><span># This config file enables a /dev/zram0 device with the default settings:</span></span>
<span class="line"><span># - size - same as available RAM or 8GB, whichever is less</span></span>
<span class="line"><span># - compression - most likely lzo-rle</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># To disable, uninstall zram-generator-defaults or create empty</span></span>
<span class="line"><span># /etc/systemd/zram-generator.conf file.</span></span>
<span class="line"><span>[zram0]zram-size= min(ram, 8192)</span></span></code></pre></div><p>你可以在 <code>zram-generator.conf</code> 配置文件的最后一行改变默认的 zram 交换空间大小。但我建议不要这样做，除非你能明确说明这样做的原因，并在你做任何改变后测试你的结果。像 Linux 中的许多其他配置默认值一样，zram 的默认值已经被很好地测试过了，适合大多数使用情况。</p><h3 id="监控-zram" tabindex="-1">监控 zram <a class="header-anchor" href="#监控-zram" aria-label="Permalink to “监控 zram”">​</a></h3><p>可以使用 <code>zramctl</code> 工具来查看 zram 的当前状态。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># zramctl</span></span>
<span class="line"><span>NAME       ALGORITHM DISKSIZE DATA COMPR TOTAL STREAMS MOUNTPOINT</span></span>
<span class="line"><span>/dev/zram0 lzo-rle       4.8G   4K   80B   12K       4[SWAP]</span></span></code></pre></div><p>传统的 <code>swapon</code> 命令也可以用来查看交换，包括作为交换使用的 zram：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># swapon --show</span></span>
<span class="line"><span>NAME       TYPE      SIZE USED PRIO</span></span>
<span class="line"><span>/dev/zram0 partition 4.8G   0B  100</span></span></code></pre></div><p>需要注意的是，<code>zramctl</code> 在不包含数据时不报告 zram，所以结果会包含空输出。而像 <code>lsblk</code>、<code>swapon</code>、 <code>top</code>、<code>free</code>、<code>htop</code> 等工具，即使不包含数据，也会显示 zram。</p><h3 id="停用-zram" tabindex="-1">停用 zram <a class="header-anchor" href="#停用-zram" aria-label="Permalink to “停用 zram”">​</a></h3><p><code>swapoff -a</code> 命令会关闭 zram 交换空间以及用作交换的传统 HDD 或 SSD 存储。<code>swapon -a</code> 命令在 zram 为空时不显示它，可以使用 <code>zramctl /dev/zram0</code> 代替。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># swapon --show# lsblk</span></span>
<span class="line"><span>NAME          MAJ:MIN RM  SIZE RO TYPE MOUNTPOINTS</span></span>
<span class="line"><span>sda             8:00  120G  0 disk</span></span>
<span class="line"><span>├─sda1          8:10    1G  0 part /boot/efi</span></span>
<span class="line"><span>├─sda2          8:20    1G  0 part /boot</span></span>
<span class="line"><span>└─sda3          8:30  118G  0 part</span></span>
<span class="line"><span>  ├─vg01-root 253:00   10G  0 lvm  /</span></span>
<span class="line"><span>  ├─vg01-swap 253:10    3G  0 lvm  [SWAP]</span></span>
<span class="line"><span>  ├─vg01-usr  253:10   30G  0 lvm  /usr</span></span>
<span class="line"><span>  ├─vg01-home 253:20   10G  0 lvm  /home</span></span>
<span class="line"><span>  ├─vg01-var  253:30   30G  0 lvm  /var</span></span>
<span class="line"><span>  └─vg01-tmp  253:40   10G  0 lvm  /tmp</span></span>
<span class="line"><span>sr0            11:01 1024M  0 rom</span></span>
<span class="line"><span>zram0         252:00    0B  0 disk</span></span>
<span class="line"><span># zramctl## zramctl /dev/zram0</span></span>
<span class="line"><span>NAME       ALGORITHM DISKSIZE DATA COMPR TOTAL STREAMS MOUNTPOINT</span></span>
<span class="line"><span>/dev/zram0 lzo-rle         0B   0B    0B    0B       4</span></span></code></pre></div><p>注意，<code>/dev/zram0</code> 在这些命令中并没有显示为交换空间，直到它被用于该目的。这给我造成了一些困惑，直到我的实验表明这是事实。</p><h3 id="创建-zram-交换空间" tabindex="-1">创建 zram 交换空间 <a class="header-anchor" href="#创建-zram-交换空间" aria-label="Permalink to “创建 zram 交换空间”">​</a></h3><p>zram 本身已经存在了大约 20 年，但只是在过去的一两年里才在一些发行版上作为交换空间使用。你的一些或所有主机上当前的 Linux 环境可能没有用 zram 创建交换空间。如果是这种情况，它可以很容易地被补救。</p><p>对于 Fedora 32，它是默认使用 zram 交换空间之前的最后一个版本，它只需要三个简单的命令。</p><p>首先，验证是否存在 <code>zram-swap.service</code> 文件，它作为 <code>zram</code> RPM 包的一部分安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl status zram-swap</span></span>
<span class="line"><span>● zram-swap.service - Enable compressed swap in memory using zram</span></span>
<span class="line"><span>     Loaded: loaded (/usr/lib/systemd/system/zram-swap.service; disabled; vendor preset: disabled)</span></span>
<span class="line"><span>     Active: inactive (dead)</span></span></code></pre></div><p>接下来，安装 <code>zram-generator-defaults</code> 和 <code>zram-generator</code> 软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install zram-generator-defaults zram-generator</span></span></code></pre></div><p>启用并启动 <code>zram-swap</code> 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl enable zram-swap.service# systemctl start zram-swap.service</span></span></code></pre></div><p>然后验证 <code>zram0</code> 是否存在并被用作交换空间：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lsblk</span></span>
<span class="line"><span>NAME          MAJ:MIN RM  SIZE RO TYPE MOUNTPOINT</span></span>
<span class="line"><span>sda             8:00  120G  0 disk</span></span>
<span class="line"><span>├─sda1          8:10    2G  0 part /boot</span></span>
<span class="line"><span>└─sda2          8:20  118G  0 part</span></span>
<span class="line"><span>  ├─vg01-root 253:00   10G  0 lvm  /</span></span>
<span class="line"><span>  ├─vg01-swap 253:10    3G  0 lvm  [SWAP]</span></span>
<span class="line"><span>  ├─vg01-usr  253:20   35G  0 lvm  /usr</span></span>
<span class="line"><span>  ├─vg01-tmp  253:30   15G  0 lvm  /tmp</span></span>
<span class="line"><span>  ├─vg01-var  253:40   35G  0 lvm  /var</span></span>
<span class="line"><span>  └─vg01-home 253:50   20G  0 lvm  /home</span></span>
<span class="line"><span>sr0            11:01 1024M  0 rom</span></span>
<span class="line"><span>zram0         252:00  7.5G  0 disk [SWAP]</span></span></code></pre></div><h3 id="用-zram-改进交换空间" tabindex="-1">用 zram 改进交换空间 <a class="header-anchor" href="#用-zram-改进交换空间" aria-label="Permalink to “用 zram 改进交换空间”">​</a></h3><p>这就是全部内容了。在 Fedora 上这很容易。不同的发行版可能也一样简单，只是软件包名称和命令的细节可能不同。在你的电脑上试试 zram 交换空间吧。在我的下一篇文章中，我将进一步演示一些 zram 选项。</p><hr>`,38)),n("p",null,[a[8]||(a[8]=s("via: ",-1)),p(e,{href:"https://opensource.com/article/22/11/zram-swap-linux"},{default:i(()=>[...a[7]||(a[7]=[s("https://opensource.com/article/22/11/zram-swap-linux",-1)])]),_:1})]),n("p",null,[a[13]||(a[13]=s("作者：",-1)),p(e,{href:"https://opensource.com/users/dboth"},{default:i(()=>[...a[9]||(a[9]=[s("David Both",-1)])]),_:1}),a[14]||(a[14]=s(" 选题：",-1)),p(e,{href:"https://github.com/lkxed"},{default:i(()=>[...a[10]||(a[10]=[s("lkxed",-1)])]),_:1}),a[15]||(a[15]=s(" 译者：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[11]||(a[11]=[s("wxy",-1)])]),_:1}),a[16]||(a[16]=s(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[12]||(a[12]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[19]||(a[19]=s("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[17]||(a[17]=[s("LCTT",-1)])]),_:1}),a[20]||(a[20]=s(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...a[18]||(a[18]=[s("Linux中国",-1)])]),_:1}),a[21]||(a[21]=s(" 荣誉推出",-1))])])}const x=r(m,[["render",c]]);export{v as __pageData,x as default};
